// KnowledgeServiceServer is the server API for KnowledgeService service.
// All implementations must embed UnimplementedKnowledgeServiceServer
// for forward compatibility.
//
// Owns the Project Knowledge Model: what exists and how it is related.
// Facts live in SQL, semantic memory in pgvector, relationships in a
// temporal graph. The GitHub connector is read-only (Observe mode).
type KnowledgeServiceServer interface {
	// --- GitHub connector -----------------------------------------------------
	GetGithubAccount(context.Context, *GetGithubAccountRequest) (*GithubAccount, error)
	ListGithubRepos(context.Context, *ListGithubReposRequest) (*ListGithubReposResponse, error)
	// --- Projects -------------------------------------------------------------
	// Connects a repository and queues its first scan.
	ConnectProject(context.Context, *ConnectProjectRequest) (*Project, error)
	ListProjects(context.Context, *ListProjectsRequest) (*ListProjectsResponse, error)
	// Connected-project counts for several workspaces in one call (the
	// gateway's workspace switcher). Internal: only the `system` principal
	// may ask across workspaces; anyone else gets their own workspace only.
	CountProjects(context.Context, *CountProjectsRequest) (*CountProjectsResponse, error)
	GetProject(context.Context, *GetProjectRequest) (*Project, error)
	DeleteProject(context.Context, *DeleteProjectRequest) (*DeleteProjectResponse, error)
	SetProjectMode(context.Context, *SetProjectModeRequest) (*Project, error)
	// --- Scans ----------------------------------------------------------------
	StartScan(context.Context, *StartScanRequest) (*Scan, error)
	GetScan(context.Context, *GetScanRequest) (*Scan, error)
	ListScans(context.Context, *ListScansRequest) (*ListScansResponse, error)
	// Live progress: emits the scan after every stage change, ends when terminal.
	WatchScan(*WatchScanRequest, grpc.ServerStreamingServer[Scan]) error
	// --- Knowledge model ------------------------------------------------------
	ListFacts(context.Context, *ListFactsRequest) (*ListFactsResponse, error)
	ListQuestions(context.Context, *ListQuestionsRequest) (*ListQuestionsResponse, error)
	AnswerQuestion(context.Context, *AnswerQuestionRequest) (*Question, error)
	GetUnderstanding(context.Context, *GetUnderstandingRequest) (*Understanding, error)
	// Delivery maturity 0–100 with per-axis findings; drives modernization proposals.
	GetMaturity(context.Context, *GetMaturityRequest) (*MaturityScore, error)
	GetGraph(context.Context, *GetGraphRequest) (*Graph, error)
	AnalyzeImpact(context.Context, *AnalyzeImpactRequest) (*ImpactAnalysis, error)
	ListDependencies(context.Context, *ListDependenciesRequest) (*ListDependenciesResponse, error)
	// --- Delivery observation -------------------------------------------------
	ListPipelines(context.Context, *ListPipelinesRequest) (*ListPipelinesResponse, error)
	ListPipelineRuns(context.Context, *ListPipelineRunsRequest) (*ListPipelineRunsResponse, error)
	ListDeployments(context.Context, *ListDeploymentsRequest) (*ListDeploymentsResponse, error)
	// --- Pattern memory and retrieval -----------------------------------------
	ListPatterns(context.Context, *ListPatternsRequest) (*ListPatternsResponse, error)
	GetPattern(context.Context, *GetPatternRequest) (*Pattern, error)
	// Closes the loop: an execution outcome updates the pattern it came from.
	RecordPatternOutcome(context.Context, *RecordPatternOutcomeRequest) (*Pattern, error)
	SearchKnowledge(context.Context, *SearchKnowledgeRequest) (*SearchKnowledgeResponse, error)
	// Lets other services store text (decisions, conversations) as semantic memory.
	IndexKnowledge(context.Context, *IndexKnowledgeRequest) (*IndexKnowledgeResponse, error)
	ListSimilarProjects(context.Context, *ListSimilarProjectsRequest) (*ListSimilarProjectsResponse, error)
	// --- Service-to-service ---------------------------------------------------
	// Everything the proposal engine needs about one project, in one call.
	GetProjectContext(context.Context, *GetProjectContextRequest) (*ProjectContext, error)
	GetKnowledgeStats(context.Context, *GetKnowledgeStatsRequest) (*KnowledgeStats, error)
	// --- Code browser ---------------------------------------------------------
	// The whole tree at the scanned commit, cached per scan.
	GetRepoTree(context.Context, *GetRepoTreeRequest) (*RepoTree, error)
	// One file's text at the scanned commit (GitHub contents API, cached).
	GetRepoFile(context.Context, *GetRepoFileRequest) (*RepoFile, error)
	// --- Pull requests (code review input) ------------------------------------
	ListPullRequests(context.Context, *ListPullRequestsRequest) (*ListPullRequestsResponse, error)
	// One PR with its changed files and unified diff hunks (bounded).
	GetPullRequest(context.Context, *GetPullRequestRequest) (*PullRequest, error)
	// Whether one PR can be merged right now, read from GitHub at call time:
	// mergeability, checks, approvals, allowed merge methods (CONTRACT.md §23).
	GetPullRequestStatus(context.Context, *GetPullRequestStatusRequest) (*PullRequestStatus, error)
	// --- Security (CONTRACT.md §23) -------------------------------------------
	// Dependabot's state for the repository and its open alerts.
	GetRepositorySecurity(context.Context, *GetRepositorySecurityRequest) (*RepositorySecurity, error)
	// --- Settings and live events ---------------------------------------------
	GetSettings(context.Context, *GetSettingsRequest) (*KnowledgeSettings, error)
	UpdateSettings(context.Context, *UpdateSettingsRequest) (*KnowledgeSettings, error)
	// Project, scan and pattern changes as they happen. Never ends.
	WatchEvents(*v1.WatchEventsRequest, grpc.ServerStreamingServer[v1.PlatformEvent]) error
	// --- Data controls (CONTRACT.md §19) ---------------------------------------
	// Drops every cached file (and tree) of the caller's workspace, or of one
	// project. ADMIN.
	PurgeCodeCache(context.Context, *PurgeCodeCacheRequest) (*PurgeCodeCacheResponse, error)
	// Deletes everything the knowledge schema holds for the workspace: projects
	// and all their rows, learned patterns, settings. OWNER. Real deletion.
	DeleteWorkspaceData(context.Context, *DeleteWorkspaceDataRequest) (*DeleteWorkspaceDataResponse, error)
	// Streams every stored row of the workspace as JSON lines. ADMIN.
	ExportWorkspaceData(*ExportWorkspaceDataRequest, grpc.ServerStreamingServer[ExportRecord]) error
	mustEmbedUnimplementedKnowledgeServiceServer()
}

